def run(xs):
    acc = 0
    for i, x in enumerate(xs):
        branch = x % 3
        if branch == 0:
            acc = (acc * 7 + x) % 1000003
        elif branch == 1:
            shift = i if i < 5 else 5
            acc = (acc ^ (x << shift)) % 1000003
        else:
            acc = (acc + x * x) % 1000003
    return acc
